'use strict';

// MODULES //

var sqrt = require( '@stdlib/math/base/special/sqrt' );
var exp = require( '@stdlib/math/base/special/exp' );
var ln = require( '@stdlib/math/base/special/ln' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var poly1 = require( './rational_p1q1.js' );
var poly2 = require( './rational_p2q2.js' );
var poly3 = require( './rational_p3q3.js' );


// VARIABLES //

var Y_SMALL = 8.69547128677368164e-02;
var Y_LARGE = 1.45034217834472656;
var LOG_MAX = 709.782712893384;


// MAIN //

/**
* Computes the modified Bessel function of the second kind of order one.
*
* ## Notes
*
* -   The function has a pole at `x = 0` (behaves like 1/x).
* -   Accuracy for subnormal `x` is very poor. Full accuracy is achieved at approximately `1.0e-308` but degrades rapidly as `x → 0`.
*
* @param {number} x - input value
* @returns {number} evaluated Bessel function
*
* @example
* var v = k1( 0.0 );
* // returns Infinity
*
* @example
* var v = k1( 1.0 );
* // returns ~0.6019
*
* @example
* var v = k1( 5.0 );
* // returns ~0.004045
*
* @example
* var v = k1( -1.0 );
* // returns NaN
*
* @example
* var v = k1( Infinity );
* // returns 0.0
*/
function k1( x ) {
	var ex;
	var a;

	if ( x < 0.0 ) {
		return NaN;
	}
	if ( x === 0.0 ) {
		return PINF;
	}
	if ( x === PINF ) {
		return 0.0;
	}

	// x <= 1
	if ( x <= 1.0 ) {
		a = ( x * x ) * 0.25;
		a = ( ( poly1( a ) + Y_SMALL ) * a * a ) + ( a * 0.5 ) + 1.0;
		a = a * x * 0.5;
		return ( poly2( x * x ) * x ) + ( 1.0 / x ) + ( ln( x ) * a );
	}

	// x > 1
	if ( x < LOG_MAX ) {
		return ( poly3( 1.0 / x ) + Y_LARGE ) *
			exp( -x ) / sqrt( x );
	}

	// overflow-safe
	ex = exp( -x * 0.5 );
	return ( poly3( 1.0 / x ) + Y_LARGE ) *
		ex / sqrt( x ) * ex;
}


// EXPORTS //

module.exports = k1;
